//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns a bounded exponential delay for a zero-based retry index.
    pub fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let growth = if retry_index >= u64::BITS {
            u64::MAX
        } else {
            1_u64 << retry_index
        };
        self.base_delay_ms
            .saturating_mul(growth)
            .min(self.max_delay_ms)
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let attempts = config.max_attempts.max(1);

    for attempt in 0..attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) if attempt + 1 == attempts => return Err(error),
            Err(_) => sleeper.sleep_ms(config.delay_for_retry(attempt)),
        }
    }

    unreachable!("retry loop always returns from an attempt")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("try again".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(2, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });

        assert_eq!(
            result,
            Err(RetryError::Transient("still unavailable".into()))
        );
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![10]);
    }

    #[test]
    fn delay_growth_saturates_without_overflow() {
        let config = config(u32::MAX, u64::MAX / 2 + 1, u64::MAX);
        assert_eq!(config.delay_for_retry(0), u64::MAX / 2 + 1);
        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn run_job_retries_transient_failures_and_saturates_delay() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 7,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 4 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary outage".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![7, 10, 10]);
}

#[test]
fn run_job_returns_permanent_failure_without_sleeping() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_initial_call() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 3,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(
        result,
        Err(RetryError::Transient("still unavailable".into()))
    );
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![3]);
}

#[test]
fn extreme_retry_index_does_not_overflow() {
    let config = RetryConfig {
        max_attempts: u32::MAX,
        base_delay_ms: u64::MAX / 2 + 1,
        max_delay_ms: u64::MAX,
    };

    assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
}
